327 :       interpolator.storeTime(nextStep);
328 :       for (StepHandler handler : stepHandlers) {
329 :           handler.handleStep(interpolator, lastStep);
330 :       }
331 :       stepStart = nextStep;
332 : 
333 :       if (fsal) {
334 :         // save the last evaluation for the next step
335 :         System.arraycopy(yDotK[stages - 1], 0, yDotK[0], 0, y0.length);
336 :       }
337 : 
338 :       if (manager.reset(stepStart, y) && ! lastStep) {
339 :         // some event handler has triggered changes that
340 :         // invalidate the derivatives, we need to recompute them
341 :         computeDerivatives(stepStart, y, yDotK[0]);
342 :       }
343 : 
344 :       if (! lastStep) {
345 :         // in some rare cases we may get here with stepSize = 0, for example
346 :         // when an event occurs at integration start, reducing the first step
347 :         // to zero; we have to reset the step to some safe non zero value
348 :           stepSize = filterStep(stepSize, forward, true);
349 : 
350 :         // stepsize control for next step
351 :         final double factor = Math.min(maxGrowth,
352 :                                        Math.max(minReduction,
353 :                                                 safety * Math.pow(error, exp)));
354 :         final double  scaledH    = stepSize * factor;
355 :         final double  nextT      = stepStart + scaledH;
356 :         final boolean nextIsLast = forward ? (nextT >= t) : (nextT <= t);
357 :         hNew = filterStep(scaledH, forward, nextIsLast);
358 :       }
359 : 
360 :     }
361 : 
362 :     final double stopTime = stepStart;
363 :     resetInternalState();
364 :     return stopTime;
365 : 
366 :   }"

